#include <bits/stdc++.h>
using namespace std;

typedef double db;
typedef long long ll;
typedef unsigned long long ull;
typedef pair<int, int> pii;
typedef pair<int, string> pis;
#define F first
#define S second
#define MP make_pair
#define PB push_back
const int MAXN = 11;
const int INF = 1000000000;
const int MAXNODES = 2 * MAXN * MAXN;

struct FlowEdge {
  int to, capacity, flow, rev;
  FlowEdge() {}
  FlowEdge(int t, int c, int f, int r) : to(t), capacity(c), flow(f), rev(r) {}
};

vector<FlowEdge> g[MAXNODES];
int distToLevel[MAXN*MAXN], currentEdgeIndex[MAXN*MAXN], sourceNode, sinkNode, n;
queue<int> qBfs;

void insertEdge(int u, int v, int cap) {
  g[u].emplace_back(v, cap, 0, 0);
  g[v].emplace_back(u, 0, 0, 0);
  g[u].back().rev = g[v].size() - 1;
  g[v].back().rev = g[u].size() - 1;
}

bool buildLevelGraph() {
  fill(distToLevel, distToLevel + sinkNode + 1, INF);
  distToLevel[sourceNode] = 0;
  qBfs.push(sourceNode);
  while (!qBfs.empty()) {
    int u = qBfs.front(); qBfs.pop();
    for (const auto& e : g[u]) {
      int v = e.to;
      int residual = e.capacity - e.flow;
      if (distToLevel[v] == INF && residual > 0) {
        distToLevel[v] = distToLevel[u] + 1;
        qBfs.push(v);
      }
    }
  }
  return distToLevel[sinkNode] != INF;
}

int blockingFlow(int u, int flowLimit) {
  if (u == sinkNode) return flowLimit;
  for (int& i = currentEdgeIndex[u]; i < (int)g[u].size(); ++i) {
    auto& e = g[u][i];
    int v = e.to;
    int residual = e.capacity - e.flow;
    int extra;
    if (distToLevel[v] == distToLevel[u] + 1 && residual > 0 && (extra = blockingFlow(v, min(flowLimit, residual)))) {
      e.flow += extra;
      g[v][e.rev].flow -= extra;
      return extra;
    }
  }
  return 0;
}

int maxFlow() {
  int total = 0;
  while (buildLevelGraph()) {
    memset(currentEdgeIndex, 0, sizeof(currentEdgeIndex));
    int delta;
    while ((delta = blockingFlow(sourceNode, INF))) total += delta;
  }
  return total;
}

queue<pii> workQueue;
const int dirX[] = {-1, 1, 0, 0};
const int dirY[] = {0, 0, -1, 1};
int shortestDist[MAXN][MAXN][MAXN][MAXN], timeLimit;
char boardA[MAXN][MAXN], boardB[MAXN][MAXN];
pii dangerCell;

bool inBounds(pii p) {
  return p.F >= 0 && p.F < n && p.S >= 0 && p.S < n && boardA[p.F][p.S] != 'Y' && boardA[p.F][p.S] != 'Z';
}

void bfsCompute(int x0, int y0) {
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < n; ++j)
      shortestDist[x0][y0][i][j] = INF;
  shortestDist[x0][y0][x0][y0] = 0;
  workQueue.push({x0, y0});
  while (!workQueue.empty()) {
    pii p = workQueue.front(); workQueue.pop();
    if (shortestDist[x0][y0][p.F][p.S] == shortestDist[dangerCell.F][dangerCell.S][p.F][p.S] && (dangerCell.F != x0 || dangerCell.S != y0)) continue;
    for (int k = 0; k < 4; ++k) {
      pii np = {p.F + dirX[k], p.S + dirY[k]};
      if (inBounds(np) && shortestDist[x0][y0][np.F][np.S] == INF && shortestDist[x0][y0][p.F][p.S] + 1 <= shortestDist[dangerCell.F][dangerCell.S][np.F][np.S]) {
        shortestDist[x0][y0][np.F][np.S] = shortestDist[x0][y0][p.F][p.S] + 1;
        workQueue.push(np);
      }
    }
  }
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  cin >> n >> timeLimit;
  int px, py;
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < n; ++j) {
      cin >> boardA[i][j];
      if (boardA[i][j] == 'Z') px = i, py = j;
    }
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < n; ++j)
      cin >> boardB[i][j];
  dangerCell = {px, py};
  bfsCompute(px, py);
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < n; ++j)
      shortestDist[dangerCell.F][dangerCell.S][i][j] = min(shortestDist[dangerCell.F][dangerCell.S][i][j], timeLimit);
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < n; ++j)
      if (inBounds({i, j})) bfsCompute(i, j);
  sourceNode = 0;
  sinkNode = 2 * n * n + 1;
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < n; ++j) {
      if (boardA[i][j] != '0') insertEdge(sourceNode, i * n + j + 1, boardA[i][j] - '0');
      if (boardB[i][j] != '0') insertEdge(i * n + j + 1 + n * n, sinkNode, boardB[i][j] - '0');
    }
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < n; ++j)
      for (int i1 = 0; i1 < n; ++i1)
        for (int j1 = 0; j1 < n; ++j1)
          if (inBounds({i, j}) && inBounds({i1, j1}) && shortestDist[i][j][i1][j1] <= shortestDist[px][py][i1][j1])
            insertEdge(i * n + j + 1, i1 * n + j1 + 1 + n * n, INF);
  cout << maxFlow() << '\n';
  return 0;
}
